const pattern = /hello/;

console.log(pattern.test("Hello world"));
// false

console.log(pattern.test("hello world"));
// true

// 1. Regular expression literal
const regex1 = /hello/i;

// 2. RegExp constructor
const regex2 = new RegExp("hello", "i");

console.log(regex1.test("Hello"));
// true

console.log(regex2.test("HELLO"));
// true

const regex = /hello/gi;

// g = find all matches
// i = ignore case

const text = "Hello hello HELLO";

console.log(text.match(regex));
// ["Hello", "hello", "HELLO"]

const regex = /javascript/i;
const text = "I am learning JavaScript";

// test() -> boolean
console.log(regex.test(text));
// true

// match() -> match information
console.log(text.match(regex));
// ["JavaScript"]

const text = "I have 10 apples and 20 oranges";
const regex = /(\d+) (\w+)/g;

// match()
console.log(text.match(regex));
// ["10 apples", "20 oranges"]

// matchAll()
const matches = [...text.matchAll(regex)];

console.log(matches[0][1]);
// "10"

console.log(matches[0][2]);
// "apples"

console.log(matches[1][1]);
// "20"

console.log(matches[1][2]);
// "oranges"

function isValidEmail(email) {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
}

console.log(isValidEmail("jeet@example.com"));
// true

console.log(isValidEmail("invalid-email"));
// false

